1	import { useEffect, useState } from 'react';
2	import { useCustomerType } from '@salesforce/commerce-sdk-react';
3	
4	/**
5	 * `sessionStorage` key backing the Recently Viewed empty-state gate (see
6	 * `useRecentlyViewedGate` below). Exported as a single named constant so `markProductViewed`
7	 * (the writer) and the gate (the reader) can never disagree on the key, per conventions.md's
8	 * no-magic-strings rule.
9	 */
10	export const RECENTLY_VIEWED_SESSION_KEY = 'zimm-recently-viewed';
11	
12	/**
13	 * Marks that this browser session has viewed at least one real product. Called once per
14	 * product view from the existing Einstein `useEffect` in
15	 * `overrides/app/pages/product-detail/index.tsx`, alongside the `einstein.sendViewProduct`
16	 * calls already there.
17	 *
18	 * Wrapped in try/catch: Safari private-browsing mode throws on `sessionStorage` access. On
19	 * throw this does nothing — no flag gets set — rather than throwing further and breaking the
20	 * page's own Einstein analytics call it sits beside.
21	 */
22	export const markProductViewed = (): void => {
23	  try {
24	    sessionStorage.setItem(RECENTLY_VIEWED_SESSION_KEY, 'true');
25	  } catch {
26	    // Safari private-browsing mode (or any other sessionStorage failure) — degrade silently,
27	    // no flag gets set.
28	  }
29	};
30	
31	/**
32	 * AC 8's empty-state gate (SFCC-83 build plan, finding 28): Einstein's
33	 * `viewed-recently-einstein` recommender always returns a two-product baseline for a visitor
34	 * with zero real history, so `recs.length === 0` never fires and the "nothing viewed yet"
35	 * empty state can't be read off the API response alone. This hook supplies a local boolean
36	 * instead of trusting Einstein's own list:
37	 *
38	 * `hasRecentlyViewed = sessionFlagIsSet || isRegistered`
39	 *
40	 * `sessionStorage` is genuinely session-scoped and cleared at session end (AC 6).
41	 * `isRegistered` (from `useCustomerType()` — the same hook
42	 * `@salesforce/retail-react-app/app/hooks/use-einstein.js:449` already calls) short-circuits
43	 * the local flag, so an authenticated shopper on a device they've never browsed on still gets
44	 * credit for server-side history (AC 7).
45	 *
46	 * Known residual, stated in the PR body rather than papered over here: a *registered* shopper
47	 * who has genuinely never viewed anything still sees Einstein's two-product baseline (build
48	 * plan Open Question 6).
49	 *
50	 * SSR-safe by construction: returns `false` on every render until the effect below has run, so
51	 * there is no `sessionStorage` read during the render pass SSR reproduces — no hydration
52	 * mismatch, since the rail this gates does not exist on first paint either way.
53	 *
54	 * @returns `true` once this session has viewed a product, or once the shopper is known to be
55	 *   registered — `false` otherwise, including on the very first render before this hook's own
56	 *   effect has resolved.
57	 */
58	export const useRecentlyViewedGate = (): boolean => {
59	  const { isRegistered } = useCustomerType();
60	  const [hasRecentlyViewed, setHasRecentlyViewed] = useState(false);
61	
62	  useEffect(() => {
63	    let sessionFlagIsSet = false;
64	    try {
65	      sessionFlagIsSet = sessionStorage.getItem(RECENTLY_VIEWED_SESSION_KEY) !== null;
66	    } catch {
67	      // Safari private-browsing mode (or any other sessionStorage failure) — treat as not set.
68	      sessionFlagIsSet = false;
69	    }
70	    setHasRecentlyViewed(sessionFlagIsSet || isRegistered);
71	  }, [isRegistered]);
72	
73	  return hasRecentlyViewed;
74	};
