139	/**
140	 * A component for fetching and rendering product recommendations from the Einstein API
141	 * by a zone or a recommender name.
142	 */
143	const RecommendedProducts = ({
144	  zone,
145	  recommender,
146	  products,
147	  title,
148	  shouldFetch,
149	  ...props
150	}: RecommendedProductsProps) => {
151	  const { isLoading, recommendations, getZoneRecommendations, getRecommendations, sendClickReco, sendViewReco } =
152	    useEinstein();
153	  const { data: customer } = useCurrentCustomer();
154	  const { customerId } = customer;
155	  const { data: wishlist } = useWishList();
156	  const dataCloud = useDataCloud();
157	
158	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
159	  const deleteCustomerProductListItem = useShopperCustomersMutation('deleteCustomerProductListItem');
160	  const toast = useToast();
161	  const navigate = useNavigation();
162	  const intl = useIntl();
163	  // Same split product-list/productListCardMapper.ts's own consumer uses
164	  // (product-list/index.tsx): passed into the mapper rather than formatted there, keeping that
165	  // mapper free of any react-intl dependency of its own.
166	  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });
167	
168	  const ref = useRef();
169	  const isOnScreen = useIntersectionObserver(ref, { useOnce: true });
170	  const [_products, setProducts] = useState(products);
171	  // Unconditional, alongside the hook calls above — must run on every render, including the
172	  // ones that hit the dead-code early return two blocks below, per React's rules of hooks.
173	  const hasRecentlyViewed = useRecentlyViewedGate();
174	
175	  useEffect(() => {
176	    // Check if the component should fetch results or not. This is useful
177	    // when you are still waiting on additional data, like `products`.
178	    if (typeof shouldFetch === 'function' && !shouldFetch()) {
179	      return;
180	    }
181	
182	    // Fetch either zone or recommender, but not both. If a zone and recommender
183	    // name are both provided, `zone` takes precendence.
184	    if (zone) {
185	      getZoneRecommendations(zone, _products);
186	      return;
187	    }
188	    if (recommender) {
189	      getRecommendations(recommender, _products);
190	      return;
191	    }
192	  }, [zone, recommender, _products]);
193	
194	  useEffect(() => {
195	    // This is an optimization that eliminates superfluous rerenders/fetching by
196	    // keeping a copy of the `products` array prop in state for shallow comparison.
197	    if (!Array.isArray(products)) {
